import assert from 'node:assert/strict';
import { beforeEach, test } from 'node:test';
import { cancelOrder, getOrder, listKitchenTickets, placeOrder, resetOrdersState, sendToKitchen } from '../src/orders.ts';
import type { OrderRequest } from '../src/orders.ts';

const ORDER: OrderRequest = {
  item: 'chicken-burger',
  omit: ['onions'],
  spice: 'extra-spicy',
  bun: 'gluten-free',
  deliverBy: '2026-09-14T19:00:00+07:00',
};

beforeEach(() => {
  resetOrdersState();
});

test('scenario: place-order', () => {
  const result = placeOrder('order-1', 'customer-a', ORDER);
  assert.deepEqual(result, { status: 201, orderId: 'order-1' });

  const duplicate = placeOrder('order-1', 'customer-a', ORDER);
  assert.deepEqual(duplicate, { status: 409 });

  const order = getOrder('order-1');
  assert.ok(order);
  assert.equal(order.request.item, 'chicken-burger');
  assert.deepEqual(order.request.omit, ['onions']);
  assert.equal(order.request.spice, 'extra-spicy');
  assert.equal(order.request.bun, 'gluten-free');
  assert.equal(order.request.deliverBy, '2026-09-14T19:00:00+07:00');
});

test('scenario: cancel-order', () => {
  placeOrder('order-1', 'customer-a', ORDER);

  const result = cancelOrder('order-1');
  assert.deepEqual(result, { status: 204 });

  const second = cancelOrder('order-1');
  assert.deepEqual(second, { status: 404 });

  assert.equal(getOrder('order-1'), null);
});

test('scenario: send-order-to-kitchen', () => {
  placeOrder('order-1', 'customer-a', ORDER);

  const result = sendToKitchen('order-1');
  assert.equal(result.status, 201);
  assert.equal(result.status === 201 ? result.ticket.orderId : null, 'order-1');
  assert.equal(result.status === 201 ? result.ticket.item : null, 'chicken-burger');

  const unknown = sendToKitchen('order-404');
  assert.deepEqual(unknown, { status: 404 });
});

test('scenario: gluten-free-bun-reaches-kitchen', () => {
  placeOrder('order-1', 'customer-a', ORDER);

  sendToKitchen('order-1');

  const [ticket] = listKitchenTickets();
  assert.ok(ticket);
  assert.equal(ticket.bun, 'gluten-free');
});

test('scenario: Omitted ingredients appear on ticket', () => {
  placeOrder('order-1', 'customer-a', ORDER);

  const result = sendToKitchen('order-1');
  assert.equal(result.status, 201);
  assert.deepEqual(result.status === 201 ? result.ticket.omit : null, ['onions']);
});

test('scenario: Spice level is shown exactly as ordered', () => {
  placeOrder('order-1', 'customer-a', { ...ORDER, spice: 'medium' });

  const result = sendToKitchen('order-1');
  assert.equal(result.status, 201);
  assert.equal(result.status === 201 ? result.ticket.spice : null, 'medium');
});

test('scenario: Delivery time is shown exactly as ordered', () => {
  placeOrder('order-1', 'customer-a', ORDER);

  const result = sendToKitchen('order-1');
  assert.equal(result.status, 201);
  assert.equal(
    result.status === 201 ? result.ticket.deliverBy : null,
    '2026-09-14T19:00:00+07:00',
  );
});

test('scenario: Bun choice is shown exactly as ordered', () => {
  placeOrder('order-1', 'customer-a', { ...ORDER, bun: 'regular' });

  const result = sendToKitchen('order-1');
  assert.equal(result.status, 201);
  assert.equal(result.status === 201 ? result.ticket.bun : null, 'regular');
});

test('scenario: listKitchenTickets returns matching ticket fields', () => {
  const request: OrderRequest = {
    item: 'Bacon Cheeseburger',
    omit: ['onions'],
    spice: 'extra-spicy',
    bun: 'regular',
    deliverBy: '2026-09-14T19:00:00+07:00',
  };
  placeOrder('order-1', 'customer-a', request);
  sendToKitchen('order-1');

  const tickets = listKitchenTickets();
  assert.equal(tickets.length, 1);
  const [ticket] = tickets;
  assert.equal(ticket.item, 'Bacon Cheeseburger');
  assert.equal(ticket.bun, 'regular');
  assert.deepEqual(ticket.omit, ['onions']);
  assert.equal(ticket.spice, 'extra-spicy');
  assert.equal(ticket.deliverBy, '2026-09-14T19:00:00+07:00');
});

